println("=== Chiffren-Werkstatt ===");
println("Caesar(FUNKSTILLE, 3)   = " + Bausteine.caesar("FUNKSTILLE", 3));
println("Vigenere(WETTERBERICHT, FUNK) = " + Bausteine.vigenere("WETTERBERICHT", "FUNK"));
println("Gartenzaun(FERNSCHREIBER, 3) = " + Bausteine.gartenzaun("FERNSCHREIBER", 3));
println("Spalten(FERNSCHREIBER, ZUG) = " + Bausteine.spaltentransposition("FERNSCHREIBER", "ZUG"));
